import math, itertools, random
from air_quality.warning import (
    level_probability, alert_run, alert_run_distribution, alert_run_profile,
)

random.seed(0)
def run_case(K, N, m):
    vals = [[random.uniform(0, 5) for _ in range(N)] for _ in range(K)]
    unc = [[random.uniform(0, 0.5) for _ in range(N)] for _ in range(K)]
    pop = [random.uniform(0.5, 3) for _ in range(N)]
    beta = random.uniform(0.5, 2.0)
    thr = [1.0, 2.0, 3.0]
    q = level_probability(vals, unc, pop, beta, thr)[2]
    q0, first0, pany0 = alert_run(vals, unc, pop, beta, thr, m)
    qd, distd, exd = alert_run_distribution(vals, unc, pop, beta, thr, m)
    qp, distp, exp, firstp, cump = alert_run_profile(vals, unc, pop, beta, thr, m)
    assert qp == q == q0 == qd
    assert distp == distd
    assert exp == exd
    assert firstp == first0
    brute_dist = [0.0] * (K + 1)
    brute_first = [0.0] * K
    for bits in itertools.product((0.0, 1.0), repeat=K):
        pr = 1.0
        r = c = 0
        fdone = False
        for t, b in enumerate(bits):
            pr *= q[t] if b else (1.0 - q[t])
            if b:
                if r < m:
                    r += 1
                    if r == m:
                        c += 1
                        if not fdone:
                            brute_first[t] += pr
                            fdone = True
            else:
                r = 0
        brute_dist[c] += pr
    for c in range(K + 1):
        if not math.isclose(distp[c], brute_dist[c], rel_tol=1e-12, abs_tol=1e-12):
            print("DIST FAIL", K, N, m, c, distp[c], brute_dist[c], q, distp, brute_dist)
            return False
    return True

idx=0
for K in range(1, 8):
    for N in (1, 2, 3):
        for m in range(1, min(K, 4) + 1):
            for _ in range(30):
                if not run_case(K, N, m):
                    raise SystemExit
                idx += 1
print("all OK", idx)
